select id, supplier_name, city, rating, lag(rating) over (partition by country order by rating, id) as prev_rating, lead(rating) over (partition by country order by rating, id) as next_rating, row_number() over (partition by country order by rating, id) as seq_no, sum(rating) over (partition by city order by rating, id rows between unbounded preceding and current row) as running_rating from suppliers;
